"""Vocabulary: what words and phrases mean, built from the catalogue plus synonym tables.

The `Lexicon` answers "does a category, colour, brand or size start at this token?" with the
longest phrase that matches. It does not decide what a mention *means* in context (a late
constraint, a correction): that is slot extraction and filter state.

Where the words come from
  * exact words: every category, colour, brand and letter size in `catalogue.csv`;
  * variants of those, generated by rule: plural and singular ("shirt" for "shirts"), hyphen
    and spacing forms ("t-shirt", "t shirt", "tshirt", "bagpack");
  * synonyms listed below. This is a HAND-WRITTEN SEED LEXICON, and it should be read as one.
    Entries without a comment were met while reading dev.jsonl in Stage 1; entries marked "not
    seen in dev" are my own guesses at wording the hidden set may use. A synonym nobody listed
    ("trainers", "kicks") is simply not understood: the agent then waits and answers at the end,
    it never commits on a word it does not know. Replacing the lists with something learned
    (pretrained word vectors as a soft lexicon) is planned for after Round 1.

Safety rules
  * Matching is on whole normalised tokens, never substrings.
  * Exact beats variant beats synonym. Two synonyms of equal rank that disagree cancel out and
    are reported in `Lexicon.conflicts` (a test requires it to stay empty).
  * Misspelled words are corrected before lookup by `spelling.SpellingCorrector`, which this
    class builds from its own vocabulary; see that module for its guards.
"""
import csv
import re
from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, FrozenSet, Iterable, List, Optional, Sequence, Set, Tuple

from .config import DEFAULT_CONFIG, SpellingConfig, VocabConfig
from .spelling import SpellingCorrector
from .tokens import Token

DEFAULT_CATALOGUE_PATH = Path(__file__).resolve().parents[1] / "catalogue.csv"

# ----------------------------------------------------------------------------- synonym tables

CATEGORY_SYNONYMS = {
    "running shoes": ["running sneakers", "jogging shoes", "runners",
                      # not seen in dev:
                      "sports shoes", "sport shoes", "jogging sneakers"],
    "sneakers": ["casual shoes", "casual sneakers"],
    "sandals": ["slides", "floaters",
                # not seen in dev:
                "flip flops", "chappals"],
    "t-shirts": ["tshirt", "tee", "t shirt",
                 # not seen in dev:
                 "tee shirt"],
    "jeans": ["denims", "denim"],
    "track pants": ["trackpants", "joggers",
                    # not seen in dev:
                    "trackies", "sweatpants"],
    "hoodies": ["hooded sweatshirt", "sweatshirt",
                # not seen in dev:
                "hoody"],
    "backpacks": ["bag pack", "rucksack", "bag",
                  # not seen in dev:
                  "back pack", "bagpack"],
    "headphones": ["headset",
                   # not seen in dev:
                   "earphones", "earbuds", "head phones"],
    "watches": ["wrist watch", "wristwatch",
                # not seen in dev:
                "smartwatch", "smart watch", "ghadi"],
    # not seen in dev:
    "kurtas": ["kurti"],
    "dresses": ["frock"],
    "jackets": ["coat", "windcheater"],
    "caps": ["topi"],
    "wallets": ["purse"],
}

COLOUR_SYNONYMS = {
    "grey": ["gray"],
    "gold": ["golden",
             # not seen in dev:
             "sunehri", "sunahri"],
    "navy": ["navy blue"],
    "olive": ["olive green"],
    "black": ["kaala",
              # not seen in dev:
              "kala", "kaali", "kali"],
    "red": ["laal",
            # not seen in dev:
            "lal"],
    "pink": ["gulabi"],
    "brown": ["bhura",
              # not seen in dev:
              "bhoora", "bhuri"],
    # not seen in dev (Hindi colour words, same family as the four above):
    "white": ["safed", "safaid"],
    "blue": ["neela", "nila", "neeli", "nili"],
    "green": ["hara", "hari"],
    "yellow": ["peela", "pila", "peeli", "pili"],
    "silver": ["chandi"],
}

SIZE_SYNONYMS = {
    "S": ["small"],
    "M": ["medium", "med"],
    "L": ["large"],
    "XL": ["extra large", "xlarge", "x large"],
    "XS": ["extra small", "xsmall", "x small"],
    "XXL": ["double xl", "2xl", "xx large", "xxlarge", "double extra large",
            "extra extra large"],
}

# ----------------------------------------------------------------------------- cue words
# Plain data for later stages. Each is a set of normalised tokens or token tuples.

# Words that introduce or follow a budget ("under 1500", "1500 tak", "within Rs. 1500").
PRICE_CUES: FrozenSet[Tuple[str, ...]] = frozenset({
    ("under",), ("below",), ("within",), ("max",), ("maximum",), ("upto",), ("up", "to"),
    ("less", "than"), ("not", "more", "than"), ("no", "more", "than"), ("cheaper", "than"),
    ("budget",), ("tak",), ("se", "kam"), ("ke", "andar"), ("rs",), ("rupees",), ("rupee",),
    ("inr",),
    # "cap" is also a category: these cues claim it ("price cap 2000" is a budget, not a cap)
    ("price", "cap"), ("budget", "cap"), ("spending", "cap"),
})

# Words that mark the next or previous number as a size ("size 9", "UK 10", "32 waist").
# "saiz" and "siz" are how "size" is often spelt in Hinglish; a typo-correction cannot reach them.
SIZE_CUES: FrozenSet[str] = frozenset({"size", "sz", "uk", "number", "waist", "saiz", "siz"})

# Words that often announce a correction (Stage 4 decides what they mean in context).
CORRECTION_WORDS: FrozenSet[str] = frozenset({
    "oops", "whoops", "sorry", "actually", "wait", "meant", "mean", "rather", "matlab",
    "nahi", "nahin", "instead", "change", "scratch", "no", "correction", "ignore", "disregard",
})

# Prior weight of a cue word in spelling correction (catalogue words use their row counts).
CUE_WORD_WEIGHT = 20.0

# Words that often open an afterthought ("and in navy", "oh, and size M").
LATE_WORDS: FrozenSet[str] = frozenset({"and", "also", "aur", "plus", "oh", "additionally"})

# Hindi and English filler: they carry no product constraint, so the unknown-word detector must not
# take them for one ("mere liye dress", "uh, navy shirt"). A small closed class, like the cue sets.
FILLER_WORDS: FrozenSet[str] = frozenset({
    "uh", "um", "umm", "hmm", "hm", "er", "erm", "ah", "ok", "okay", "yeah",
    "gimme", "lemme", "wanna", "gonna", "gotta", "plz", "pls", "yo", "bro", "dude", "kindly", "hii",
    "liye", "mere", "mujhe", "chahiye", "chahie", "dikhao", "dikha", "dikhana", "milega", "milegi",
    "hai", "hain", "kya", "aapke", "aapka", "paas", "bhaiya", "bhai", "yaar", "na",
    "wala", "wali", "wale", "ka", "ki", "ke", "ko", "se", "mein", "me", "baat", "kuch",
})

# ----------------------------------------------------------------------------- data types

_PRIORITY = {"exact": 0, "variant": 1, "synonym": 2}


@dataclass(frozen=True)
class PhraseMatch:
    slot: str           # "category", "colour", "brand" or "size"
    value: str          # the catalogue value, exactly as in catalogue.csv
    length: int         # tokens used
    kind: str           # "exact", "variant", "synonym" or "fuzzy"
    confidence: float


@dataclass(frozen=True)
class _Entry:
    slot: str
    value: str
    kind: str


# ----------------------------------------------------------------------------- helpers

def load_rows(path: Optional[Path] = None) -> List[Dict[str, str]]:
    """Read the catalogue. Used only to build vocabularies, never to look products up."""
    with open(path or DEFAULT_CATALOGUE_PATH, newline="", encoding="utf-8") as fh:
        return list(csv.DictReader(fh))


def _inflections(word: str) -> Set[str]:
    """Plural and singular forms of a noun. Short words are left alone."""
    forms = {word}
    if len(word) <= 2:
        return forms
    if word.endswith("ss"):
        forms.add(word + "es")                           # dress -> dresses
    elif word.endswith(("ches", "shes", "sses", "xes", "zes")):
        forms.add(word[:-2])                             # watches -> watch
    elif word.endswith("s"):
        forms.add(word[:-1])                             # shirts -> shirt, jeans -> jean
    else:
        forms.add(word + "s")
        if word.endswith(("ch", "sh", "x", "z")):
            forms.add(word + "es")
    return forms


def _spellings(parts: Sequence[str]) -> Set[Tuple[str, ...]]:
    """Spaced, hyphenated and joined spellings of a phrase, as token tuples."""
    keys = {tuple(parts)}
    if len(parts) > 1:
        keys.add(("-".join(parts),))
        keys.add(("".join(parts),))
    return keys


# ----------------------------------------------------------------------------- the lexicon

class Lexicon:
    def __init__(self, rows: Iterable[Dict[str, str]], config: Optional[VocabConfig] = None,
                 spelling: Optional[SpellingConfig] = None):
        rows = list(rows)
        self.config = config or DEFAULT_CONFIG.vocab
        self.categories: FrozenSet[str] = frozenset(r["category"] for r in rows)
        self.colours: FrozenSet[str] = frozenset(r["colour"] for r in rows)
        self.brands: FrozenSet[str] = frozenset(r["brand"] for r in rows)
        sizes_by_category: Dict[str, Set[str]] = defaultdict(set)
        for r in rows:
            if r["size"]:
                sizes_by_category[r["category"]].add(r["size"])
        self._sizes_by_category = {c: frozenset(s) for c, s in sizes_by_category.items()}
        all_sizes = set().union(*self._sizes_by_category.values()) if sizes_by_category else set()
        self.letter_sizes: FrozenSet[str] = frozenset(s for s in all_sizes if not s.isdigit())
        self.numeric_sizes: FrozenSet[str] = frozenset(s for s in all_sizes if s.isdigit())
        self.unsized_categories: FrozenSet[str] = self.categories - frozenset(sizes_by_category)

        self.conflicts: List[Tuple[Tuple[str, ...], List[Tuple[str, str]]]] = []
        self._table: Dict[Tuple[str, ...], _Entry] = {}
        self._build()
        self.known_words: FrozenSet[str] = frozenset(
            {w for key in self._table for w in key}
            | {w for cue in PRICE_CUES for w in cue} | SIZE_CUES | CORRECTION_WORDS | LATE_WORDS
            | FILLER_WORDS)
        self.catalogue_words: FrozenSet[str] = frozenset(
            w for r in rows for text in (r.get("title", ""), r.get("description", ""))
            for w in re.findall(r"[a-z]+", text.lower()))
        self.word_weights = self._word_weights(rows)
        # Cue words ("size", "under", "sorry") are corrected too: "saiz 10" is still a size. They
        # join the vocabulary with a small weight so a product word is never pulled towards them.
        cue_words = ({w for cue in PRICE_CUES for w in cue} | SIZE_CUES | CORRECTION_WORDS
                     | LATE_WORDS)
        weights = dict(self.word_weights)
        for w in cue_words:
            weights.setdefault(w, CUE_WORD_WEIGHT)
        self.corrector = SpellingCorrector(
            weights, self.catalogue_words - frozenset(weights),
            spelling or DEFAULT_CONFIG.spelling)
        self._max_phrase_len = max(len(key) for key in self._table)
        self._confidence = {
            "exact": self.config.confidence_exact,
            "variant": self.config.confidence_variant,
            "synonym": self.config.confidence_synonym,
        }

    @classmethod
    def from_catalogue(cls, path: Optional[Path] = None, config: Optional[VocabConfig] = None,
                       spelling: Optional[SpellingConfig] = None) -> "Lexicon":
        return cls(load_rows(path), config, spelling)

    def _word_weights(self, rows: Sequence[Dict[str, str]]) -> Dict[str, float]:
        """How common each word that names a product is: the prior of the spelling corrector.

        A word's weight is the number of catalogue rows whose category, colour or brand
        contains it. Words that only occur in listed synonyms count a third as much.
        """
        rows_with = defaultdict(int)
        for r in rows:
            for slot in ("category", "colour", "brand"):
                for w in re.split(r"[\s\-]+", r[slot].lower()):
                    rows_with[w] += 1
        weights: Dict[str, float] = {w: float(n) for w, n in rows_with.items() if w}
        for key, entry in self._table.items():
            for w in key:
                for part in re.split(r"[\s\-]+", w):
                    if part.isalpha() and part not in weights:
                        weights[part] = 1.0
        return weights

    # -- building ----------------------------------------------------------------------------

    def _build(self) -> None:
        candidates: List[Tuple[Tuple[str, ...], str, str, str]] = []

        def collect(phrase: str, slot: str, value: str, kind: str, inflect: bool = False):
            parts = [p for p in re.split(r"[\s\-]+", phrase.lower()) if p]
            base = tuple(phrase.lower().split())
            tails = _inflections(parts[-1]) if inflect else {parts[-1]}
            for tail in tails:
                for key in _spellings(parts[:-1] + [tail]):
                    derived = "variant" if kind == "exact" else kind
                    candidates.append((key, slot, value, kind if key == base else derived))

        for value in self.categories:
            collect(value, "category", value, "exact", inflect=True)
        for value in self.colours:
            collect(value, "colour", value, "exact")
        for value in self.brands:
            collect(value, "brand", value, "exact")
        for value in self.letter_sizes:
            collect(value, "size", value, "exact")

        for value, phrases in CATEGORY_SYNONYMS.items():
            if value in self.categories:
                for phrase in phrases:
                    collect(phrase, "category", value, "synonym", inflect=True)
        for value, phrases in COLOUR_SYNONYMS.items():
            if value in self.colours:
                for phrase in phrases:
                    collect(phrase, "colour", value, "synonym")
        for value, phrases in SIZE_SYNONYMS.items():
            if value in self.letter_sizes:
                for phrase in phrases:
                    collect(phrase, "size", value, "synonym")

        resolved: Set[Tuple[str, ...]] = set()
        for rank in sorted(set(_PRIORITY.values())):
            by_key: Dict[Tuple[str, ...], Set[Tuple[str, str, str]]] = defaultdict(set)
            for key, slot, value, kind in candidates:
                if _PRIORITY[kind] == rank and key not in resolved:
                    by_key[key].add((slot, value, kind))
            for key, options in by_key.items():
                resolved.add(key)
                meanings = sorted({(slot, value) for slot, value, _ in options})
                if len(meanings) == 1:
                    slot, value, kind = next(iter(options))
                    self._table[key] = _Entry(slot, value, kind)
                else:
                    self.conflicts.append((key, meanings))

    # -- queries -----------------------------------------------------------------------------

    def lookup(self, tokens: Sequence[Token], i: int) -> Optional[PhraseMatch]:
        """The longest known phrase starting at tokens[i], or None.

        A phrase of two or more words is still one phrase when a comma or full stop sits inside
        it ("navy, blue", "t, shirt", "extra, large"): the whole phrase has to be a known one,
        so a pause between two separate values ("black, white") is not merged."""
        limit = min(self._max_phrase_len, len(tokens) - i)
        for n in range(limit, 0, -1):
            entry = self._table.get(tuple(t.text for t in tokens[i:i + n]))
            if entry:
                return PhraseMatch(entry.slot, entry.value, n, entry.kind,
                                   self._confidence[entry.kind])
        return None

    def category_has_sizes(self, category: str) -> bool:
        """Vocabulary-level fact used by the search gate: do products of this category have sizes?"""
        return category in self._sizes_by_category

    def sizes_for_category(self, category: str) -> FrozenSet[str]:
        return self._sizes_by_category.get(category, frozenset())

    def size_from_number(self, value: int, category: Optional[str] = None) -> Optional[str]:
        """The catalogue size for a number such as 9 or 32, or None if no such size exists.

        With a known category the number must be one of that category's sizes (9 is a shoe size,
        32 a waist size); for a category without sizes it is never a size.
        """
        if category in self.unsized_categories:
            return None
        text = str(value)
        pool = self.sizes_for_category(category) if category in self._sizes_by_category \
            else self.numeric_sizes
        return text if text in pool else None
